    AncientCulture.EGYPT -> when (body) {
        Planet.SUN -> "your day's work"
        Planet.MOON -> "your moods"
        Planet.MERCURY -> "your letters"
        Planet.VENUS -> "your beloved"
        Planet.MARS -> "your temper"
        Planet.JUPITER -> "your patrons"
        Planet.SATURN -> "your duties"
        Planet.URANUS -> "your plans for the new season"
        Planet.NEPTUNE -> "your dreams"
        Planet.PLUTO -> "what you have buried"
    }

    AncientCulture.GREECE -> when (body) {
        Planet.SUN -> "your name in the city"
        Planet.MOON -> "your household"
        Planet.MERCURY -> "your errands"
        Planet.VENUS -> "your desire"
        Planet.MARS -> "your fighting strength"
        Planet.JUPITER -> "your standing with the powerful"
        Planet.SATURN -> "your old obligations"
        Planet.URANUS -> "your sudden notions"
        Planet.NEPTUNE -> "your wandering thoughts"
        Planet.PLUTO -> "your hidden wealth"
    }

    AncientCulture.CANAAN -> when (body) {
        Planet.SUN -> "your daily labor"
        Planet.MOON -> "your kin at home"
        Planet.MERCURY -> "your handiwork"
        Planet.VENUS -> "your love"
        Planet.MARS -> "your hot blood"
        Planet.JUPITER -> "your harvest"
        Planet.SATURN -> "your elders' rules"
        Planet.URANUS -> "your change of pasture"
        Planet.NEPTUNE -> "your prayers"
        Planet.PLUTO -> "your grain pits"
    }

    AncientCulture.CARTHAGE -> when (body) {
        Planet.SUN -> "your credit in the harbor"
        Planet.MOON -> "your household accounts"
        Planet.MERCURY -> "your contracts"
        Planet.VENUS -> "your pleasure fund"
        Planet.MARS -> "your war chest"
        Planet.JUPITER -> "your profits"
        Planet.SATURN -> "your fixed dues"
        Planet.URANUS -> "your new routes"
        Planet.NEPTUNE -> "your sea voyages"
        Planet.PLUTO -> "the debts you inherited"
    }

    AncientCulture.ROME -> when (body) {
        Planet.SUN -> "your good name"
        Planet.MOON -> "your household affairs"
        Planet.MERCURY -> "your dispatches"
        Planet.VENUS -> "your courtship"
