                Planet.PLUTO -> "A buried coin turns up, and someone will ask who spends it."
                else -> error("$partner has no consequences line")
            }
            AspectType.SEXTILE -> when (partner) {
                Planet.SUN -> "A good word in the right ear lifts your name."
                Planet.MERCURY -> "One short question earns a clear answer."
                Planet.VENUS -> "A small courtesy opens a door that force would not."
                Planet.MARS -> "A brief effort settles the matter."
                Planet.JUPITER -> "One plain question opens the way to someone powerful."
                Planet.SATURN -> "An old debt eases if you pay a little now."
                Planet.URANUS -> "A stranger brings you a useful idea."
